#include <zephyr/ztest.h>
#include <zephyr/drivers/retained_mem.h>
#include <string.h>

#define RETAINED_MEM_NODE DT_ALIAS(retained_mem0)

#if !DT_NODE_EXISTS(RETAINED_MEM_NODE)
#error "retained_mem0 alias is not defined in the devicetree"
#endif

static const struct device *retained_mem_dev;

static void retained_mem_api_test_init(void)
{
	retained_mem_dev = DEVICE_DT_GET(RETAINED_MEM_NODE);
	zassert_true(device_is_ready(retained_mem_dev), "Retained memory device is not ready");
}

static void retained_mem_api_test_write_read(void)
{
	uint8_t write_buf[32];
	uint8_t read_buf[32];

	for (int i = 0; i < sizeof(write_buf); i++) {
		write_buf[i] = i % 0xFF;
	}

	int ret = retained_mem_write(retained_mem_dev, 0, write_buf, sizeof(write_buf));
	zassert_equal(ret, 0, "Failed to write to retained memory");

	memset(read_buf, 0, sizeof(read_buf));
	ret = retained_mem_read(retained_mem_dev, 0, read_buf, sizeof(read_buf));
	zassert_equal(ret, 0, "Failed to read from retained memory");

	zassert_mem_equal(write_buf, read_buf, sizeof(write_buf), "Data not equal after write");
}

static void retained_mem_api_test_clear(void)
{
	uint8_t write_buf[32];
	uint8_t read_buf[32];
	uint8_t expected_clear_buf[32];

	for (int i = 0; i < sizeof(write_buf); i++) {
		write_buf[i] = i % 0xFF;
	}

	int ret = retained_mem_write(retained_mem_dev, 0, write_buf, sizeof(write_buf));
	zassert_equal(ret, 0, "Failed to write to retained memory");

	ret = retained_mem_clear(retained_mem_dev);
	if (ret == -ENOTSUP) {
		ztest_skip("retained_mem_clear not supported");
		return;
	}
	zassert_equal(ret, 0, "Failed to clear retained memory");

	memset(read_buf, 0xFF, sizeof(read_buf));
	ret = retained_mem_read(retained_mem_dev, 0, read_buf, sizeof(read_buf));
	zassert_equal(ret, 0, "Failed to read from retained memory after clear");

	memset(expected_clear_buf, 0, sizeof(expected_clear_buf));
	zassert_mem_equal(read_buf, expected_clear_buf, sizeof(read_buf), "data not equal to buffer");
}

ZTEST_SUITE(retained_mem_api, NULL, retained_mem_api_test_init, NULL, NULL, NULL);

ZTEST(retained_mem_api, test_write_read)
{
	retained_mem_api_test_write_read();
}

ZTEST(retained_mem_api, test_clear)
{
	retained_mem_api_test_clear();
}
